import nltk
from fastapi import FastAPI, HTTPException
from loguru import logger
from nltk.sentiment import SentimentIntensityAnalyzer
from pydantic import BaseModel, Field

nltk.download("vader_lexicon", quiet=True)
logger.add("logs/sentiment_api.log", rotation="10 MB", retention="14 days", level="INFO")
app = FastAPI(title="API sentiment")
sia = SentimentIntensityAnalyzer()

class Texte(BaseModel):
    texte: str = Field(min_length=1, max_length=5000)

@app.post("/analyse_sentiment/")
def analyse_sentiment(t: Texte) -> dict[str, float]:
    logger.info("Analyse d'un texte de {} caractères", len(t.texte))
    try:
        scores = sia.polarity_scores(t.texte)
    except Exception:
        logger.exception("Échec de l'analyse")
        raise HTTPException(status_code=500, detail="Analyse impossible") from None
    return {k: scores[k] for k in ("neg", "neu", "pos", "compound")}

