from fastapi.testclient import TestClient
from sentiment_api import app

client = TestClient(app)

def test_positif():
    r = client.post("/analyse_sentiment/", json={"texte": "I love this, it is great!"})
    assert r.status_code == 200 and r.json()["compound"] > 0.05

def test_texte_vide_refuse():
    assert client.post("/analyse_sentiment/", json={"texte": ""}).status_code == 422

def test_contrat():
    r = client.post("/analyse_sentiment/", json={"texte": "ok"})
    assert set(r.json()) == {"neg", "neu", "pos", "compound"}
